// Define the RAJA execution context (specifying CUDA backend)
// This tells RAJA to use CUDA for execution.
using namespace raja;

void run_raja_vector_add(std::vector<float>& h_A, std::vector<float>& h_B, std::vector<float>& h_C) {
    int N = h_A.size();

    // 1. Create the RAJA execution context configured for CUDA
    // The RAJA runtime handles the device memory allocation and kernel dispatch.
    auto context = make_context<cuda>();

    // 2. Create RAJA memory views (pointers/views into the data)
    // RAJA manages the transfer between host and device automatically when using these views.
    auto d_A = context.make_device_view(h_A);
    auto d_B = context.make_device_view(h_B);
    auto d_C = context.make_device_view(h_C);

    // 3. Use parallel_for to replace the kernel launch
    // RAJA maps this loop structure onto the appropriate parallel execution model (CUDA kernel).
    parallel_for(context, 0, N, [&](int i) {
        // The body of the lambda is the kernel logic
        d_C[i] = d_A[i] + d_B[i];
    });
