## Example 1: Simple Vector Addition (Element-wise Operation)

This is the most straightforward conversion, demonstrating the replacement of a simple parallel loop.

### 1. Original CUDA Code

```c++
// cuda_vector_add.cu
#include <cuda_runtime.h>
#include <stdio.h>

// CUDA Kernel
__global__ void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

void run_cuda_vector_add(float* h_A, float* h_B, float* h_C, int N) {
    // 1. Allocate device memory
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, N * sizeof(float));
    cudaMalloc((void**)&d_B, N * sizeof(float));
    cudaMalloc((void**)&d_C, N * sizeof(float));

    // 2. Copy host to device
    cudaMemcpy(d_A, h_A, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, N * sizeof(float), cudaMemcpyHostToDevice);

    // 3. Kernel Launch Configuration
    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    // 4. Launch Kernel
    vectorAddKernel<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, N);

    // 5. Copy device to host
    cudaMemcpy(h_C, d_C, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 6. Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
}
```

### 2. RAJA Portable Code

In RAJA, we use `raja::parallel_for` and let the RAJA runtime handle the device memory allocation and kernel launch based on the configured backend.

```c++
// raja_vector_add.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// Define the RAJA execution context (specifying CUDA backend)
// This tells RAJA to use CUDA for execution.
using namespace raja;

void run_raja_vector_add(std::vector<float>& h_A, std::vector<float>& h_B, std::vector<float>& h_C) {
    int N = h_A.size();

    // 1. Create the RAJA execution context configured for CUDA
    // The RAJA runtime handles the device memory allocation and kernel dispatch.
    auto context = make_context<cuda>();

    // 2. Create RAJA memory views (pointers/views into the data)
    // RAJA manages the transfer between host and device automatically when using these views.
    auto d_A = context.make_device_view(h_A);
    auto d_B = context.make_device_view(h_B);
    auto d_C = context.make_device_view(h_C);

    // 3. Use parallel_for to replace the kernel launch
    // RAJA maps this loop structure onto the appropriate parallel execution model (CUDA kernel).
    parallel_for(context, 0, N, [&](int i) {
        // The body of the lambda is the kernel logic
        d_C[i] = d_A[i] + d_B[i];
    });
}

int main() {
    const int N = 1024 * 1024;
    std::vector<float> h_A(N, 1.0f);
    std::vector<float> h_B(N, 2.0f);
    std::vector<float> h_C(N);

    std::cout << "Running RAJA Vector Addition on CUDA backend..." << std::endl;

    // Run the RAJA version
    run_raja_vector_add(h_A, h_B, h_C);

    // Verification (optional)
    std::cout << "First element result: " << h_C[0] << " (Expected: 3.0)" << std::endl;
    std::cout << "Last element result: " << h_C[N-1] << " (Expected: 3.0)" << std::endl;

    return 0;
}
```

